<script setup>
import {onBeforeUnmount,onMounted,reactive,ref} from 'vue';
const props=defineProps({mode:String,indexUrl:String,createUrl:String,storeUrl:String,updateUrl:String,csrf:String,payload:String,errors:String,old:String});
function parse(v){try{return JSON.parse(v||'{}')}catch{return {}}}
const payload=parse(props.payload),errors=parse(props.errors),old=parse(props.old),seller=payload.seller||{};
const state=reactive({rows:[],stats:{},pagination:{},filters:{search:new URLSearchParams(location.search).get('search')||'',status:new URLSearchParams(location.search).get('status')||'',sort:new URLSearchParams(location.search).get('sort')||'newest'},loading:false,error:'',form:{name:old.name??seller.name??'',email:old.email??seller.email??'',phone:old.phone??seller.phone??'',status:old.status??seller.status??'active'}});
const preview=ref(payload.photo_url||'');let abort,timer;
async function load(url=props.indexUrl,push=false){abort?.abort();abort=new AbortController();state.loading=true;state.error='';try{const r=await fetch(url,{credentials:'same-origin',signal:abort.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}}),d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to load sellers');state.rows=d.sellers||[];state.stats=d.stats||{};state.pagination=d.pagination||{};state.filters={search:'',status:'',sort:'newest',...(d.filters||{})};if(push)history.pushState({},'',url)}catch(e){if(e.name!=='AbortError')state.error=e.message}finally{state.loading=false}}
function filterUrl(){const u=new URL(props.indexUrl,location.origin);Object.entries(state.filters).forEach(([k,v])=>v&&u.searchParams.set(k,v));return u.href}function apply(){load(filterUrl(),true)}function search(){clearTimeout(timer);timer=setTimeout(apply,350)}function page(l){l.url&&load(l.url,true)}
async function updateStatus(row,status){const body=new FormData();body.append('_method','PATCH');body.append('status',status);try{const r=await fetch(row.status_url,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body});const d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to change seller status');row.status=status}catch(e){state.error=e.message}}
async function remove(row){let ok=confirm('Delete seller '+row.name+'? A seller with books cannot be deleted.');if(window.Swal){const result=await window.Swal.fire({title:'Delete seller?',text:row.name+' will be removed if no books are attached.',icon:'warning',showCancelButton:true,confirmButtonText:'Delete'});ok=result.isConfirmed}if(!ok)return;const body=new FormData();body.append('_method','DELETE');try{const r=await fetch(row.delete_url,{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,'X-Requested-With':'XMLHttpRequest'},body});const d=await r.json();if(!r.ok)throw new Error(d.message||'Unable to delete seller');load(location.href)}catch(e){state.error=e.message}}
function photoChange(e){const f=e.target.files?.[0];if(f)preview.value=URL.createObjectURL(f)}
function pop(){load(location.href)}
onMounted(()=>{if(props.mode==='index')load(props.indexUrl+location.search);window.addEventListener('popstate',pop)});onBeforeUnmount(()=>{abort?.abort();clearTimeout(timer);window.removeEventListener('popstate',pop)});
</script>
<template>
<div v-if="mode==='index'" class="dashboard-section sellers-page">
<div class="sellers-hero mb-4"><div class="sellers-hero-content"><span class="hero-badge"><i class="bi bi-shop-window"></i> Marketplace directory</span><h1>Manage your marketplace sellers.</h1><p>Review seller accounts, book activity and account status.</p></div><div class="sellers-hero-mark"><i class="bi bi-shop"></i></div></div>
<div class="row g-4 mb-4"><div v-for="item in [{key:'total',label:'Total Sellers',tone:'blue',icon:'shop'},{key:'active',label:'Active Sellers',tone:'green',icon:'person-check'},{key:'inactive',label:'Inactive Sellers',tone:'orange',icon:'pause-circle'},{key:'banned',label:'Banned Sellers',tone:'red',icon:'slash-circle'}]" :key="item.key" class="col-12 col-sm-6 col-xl-3"><div class="seller-stat-card" :class="'stat-'+item.tone"><div><span>{{item.label}}</span><strong>{{state.stats[item.key]||0}}</strong></div><i class="bi" :class="'bi-'+item.icon"></i></div></div></div>
<div class="dashboard-panel sellers-panel"><div class="panel-header sellers-panel-header"><div><span class="eyebrow">Marketplace directory</span><h5>All sellers</h5><p>Search and manage seller accounts.</p></div><a :href="createUrl" class="btn btn-primary"><i class="bi bi-plus-circle me-2"></i>Add seller</a></div>
<form class="seller-filters" @submit.prevent="apply"><div class="seller-search-field"><i class="bi bi-search"></i><input v-model="state.filters.search" name="search" placeholder="Search sellers..." @input="search"></div><select v-model="state.filters.status" class="form-select seller-status-filter"><option value="">All statuses</option><option v-for="s in ['active','inactive','banned']" :key="s">{{s}}</option></select><select v-model="state.filters.sort" class="form-select seller-sort-filter"><option value="newest">Newest</option><option value="oldest">Oldest</option><option value="name_asc">Name A-Z</option><option value="name_desc">Name Z-A</option></select><button class="btn btn-primary seller-filter-button"><i class="bi bi-funnel me-2"></i>Filter</button><button v-if="state.filters.search||state.filters.status||state.filters.sort!=='newest'" type="button" class="seller-clear-filter" @click="state.filters={search:'',status:'',sort:'newest'};apply()">Clear</button></form>
<div v-if="state.error" class="alert alert-danger m-3">{{state.error}} <button class="btn btn-sm btn-light" @click="load()">Retry</button></div><div class="sellers-table-wrap"><table class="table sellers-table align-middle"><thead><tr><th>Seller</th><th class="d-none d-md-table-cell">Email</th><th class="d-none d-lg-table-cell">Phone</th><th>Status</th><th>Books</th><th class="d-none d-xl-table-cell">Joined</th><th class="text-end">Actions</th></tr></thead><tbody><tr v-if="state.loading"><td colspan="7" class="text-center py-4">Loading sellers…</td></tr><tr v-for="row in state.rows" v-else :key="row.id"><td><div class="seller-member-cell"><img v-if="row.photo_url" :src="row.photo_url" :alt="row.name" class="seller-avatar seller-avatar-image"><span v-else class="seller-avatar">{{row.name.slice(0,1).toUpperCase()}}</span><div><strong>{{row.name}}</strong><small class="d-block">@{{row.username}}</small></div></div></td><td class="d-none d-md-table-cell"><span class="seller-email">{{row.email}}</span></td><td class="d-none d-lg-table-cell"><span class="seller-phone">{{row.phone||'—'}}</span></td><td><span class="seller-status-pill" :class="'seller-status-'+row.status"><i class="bi bi-circle-fill"></i> {{row.status}}</span></td><td><span class="book-count"><i class="bi bi-book"></i> {{row.books_count}}</span></td><td class="d-none d-xl-table-cell"><span class="seller-joined">{{row.joined}}</span></td><td><div class="seller-actions"><a :href="row.show_url" class="btn btn-light btn-sm border" title="View"><i class="bi bi-eye"></i></a><a :href="row.edit_url" class="btn btn-warning btn-sm" title="Edit"><i class="bi bi-pencil"></i></a><button v-if="!row.is_current" class="btn btn-light btn-sm border" :title="row.status==='active'?'Deactivate':'Activate'" @click="updateStatus(row,row.status==='active'?'inactive':'active')"><i class="bi" :class="row.status==='active'?'bi-pause-circle':'bi-play-circle'"></i></button><button v-if="!row.is_current&&row.status!=='banned'" class="btn btn-light btn-sm border text-danger" title="Ban" @click="updateStatus(row,'banned')"><i class="bi bi-slash-circle"></i></button><button v-if="!row.is_current" class="btn btn-danger btn-sm" title="Delete" @click="remove(row)"><i class="bi bi-trash"></i></button></div></td></tr><tr v-if="!state.loading&&!state.rows.length"><td colspan="7" class="seller-empty-state"><i class="bi bi-shop"></i><p>No sellers found.</p><a :href="createUrl" class="btn btn-primary mt-3">Add seller</a></td></tr></tbody></table></div><div v-if="state.pagination.total>10" class="sellers-pagination"><span>Showing {{state.pagination.first_item}} to {{state.pagination.last_item}} of {{state.pagination.total}}</span><nav><button v-for="(l,i) in state.pagination.links" :key="i" class="page-link" :disabled="!l.url" :class="{active:l.active}" @click="page(l)" v-html="l.label"></button></nav></div></div></div>
<div v-else-if="mode==='create'||mode==='edit'" class="dashboard-section sellers-page" :class="{'seller-edit-page':mode==='edit'}"><div class="dashboard-panel mb-4"><div class="panel-header mb-0"><span class="eyebrow">Seller management</span><h5 class="mb-1">{{mode==='create'?'Add seller':'Edit seller'}}</h5><p class="text-muted mb-0 small">{{mode==='create'?'Create a new marketplace seller account.':'Update seller profile and status.'}}</p><a :href="indexUrl" class="btn btn-light border"><i class="bi bi-arrow-left me-2"></i>Back to sellers</a></div></div><div v-if="Object.keys(errors).length" class="alert alert-danger seller-edit-alert"><ul class="mb-0"><li v-for="(e,k) in errors" :key="k">{{e[0]}}</li></ul></div><form :action="mode==='create'?storeUrl:updateUrl" method="POST" enctype="multipart/form-data" class="seller-form-panel"><input type="hidden" name="_token" :value="csrf"><input v-if="mode==='edit'" type="hidden" name="_method" value="PUT"><div class="row g-4"><div class="col-12 col-lg-8"><div class="row g-3"><div class="col-12"><label class="form-label fw-semibold" for="name">Full name <span class="text-danger">*</span></label><input id="name" v-model="state.form.name" name="name" class="form-control" required maxlength="255"><small v-if="errors.name" class="seller-field-error">{{errors.name[0]}}</small></div><div class="col-12 col-md-6"><label class="form-label fw-semibold" for="email">Email <span class="text-danger">*</span></label><input id="email" v-model="state.form.email" name="email" type="email" class="form-control" required><small v-if="errors.email" class="seller-field-error">{{errors.email[0]}}</small></div><div class="col-12 col-md-6"><label class="form-label fw-semibold" for="phone">Phone</label><input id="phone" v-model="state.form.phone" name="phone" class="form-control"></div><div class="col-12 col-md-6"><label class="form-label fw-semibold" for="password">{{mode==='create'?'Password':'New password'}}</label><input id="password" name="password" type="password" class="form-control" :required="mode==='create'" minlength="8" autocomplete="new-password"><small v-if="mode==='edit'" class="form-text text-muted">Leave blank to keep the current password.</small><small v-if="errors.password" class="text-danger">{{errors.password[0]}}</small></div><div class="col-12 col-md-6"><label class="form-label fw-semibold" for="password_confirmation">Confirm password</label><input id="password_confirmation" name="password_confirmation" type="password" class="form-control" :required="mode==='create'" autocomplete="new-password"></div></div></div><div class="col-12 col-lg-4"><div class="seller-form-side-panel"><div class="seller-form-avatar-preview"><img v-if="preview" :src="preview" alt="Seller avatar" class="seller-avatar-image"><i v-else class="bi bi-shop"></i></div><label class="form-label fw-semibold" for="profile_photo">Avatar</label><input id="profile_photo" type="file" name="profile_photo" class="form-control seller-file-input" accept="image/jpeg,image/png,image/webp" @change="photoChange"><label class="form-label fw-semibold mt-3" for="status">Status</label><select id="status" v-model="state.form.status" name="status" class="form-select"><option v-for="s in ['active','inactive','banned']" :key="s">{{s}}</option></select><p class="seller-form-note mt-3">Seller role is assigned automatically and cannot be changed.</p></div></div></div><div class="seller-form-actions mt-4"><button type="submit" class="btn btn-primary">{{mode==='create'?'Create seller':'Save changes'}}</button><a :href="indexUrl" class="btn btn-light border ms-2">Cancel</a></div></form></div>
<div v-else class="dashboard-section seller-show-page"><div class="seller-show-hero mb-4"><div class="seller-show-hero-content"><div class="seller-show-breadcrumb"><a :href="indexUrl"><i class="bi bi-shop"></i> Sellers</a><i class="bi bi-chevron-right"></i><span>Seller details</span></div><div class="seller-show-title-row"><span class="seller-show-eyebrow">Seller account</span><h1>{{seller.name}}</h1></div></div><div class="seller-show-hero-icon"><i class="bi bi-shop"></i></div></div><div class="row g-4 mb-4"><div class="col-12 col-xl-8"><div class="dashboard-panel seller-profile-panel"><div class="seller-profile-main"><div class="seller-profile-avatar-wrap"><img v-if="seller.photo_url" :src="seller.photo_url" class="seller-profile-avatar seller-profile-avatar-image" :alt="seller.name"><div v-else class="seller-profile-avatar">{{seller.name.slice(0,1).toUpperCase()}}</div></div><div class="seller-profile-info"><div class="seller-profile-name-row"><h2>{{seller.name}}</h2><span class="seller-show-status" :class="'seller-show-status-'+seller.status"><i class="bi bi-circle-fill"></i>{{seller.status}}</span></div><span class="seller-username">@{{seller.username}}</span><div class="seller-profile-meta"><span><i class="bi bi-envelope"></i>{{seller.email}}</span><span><i class="bi bi-telephone"></i>{{seller.phone||'—'}}</span><span><i class="bi bi-calendar3"></i>{{seller.created_at}}</span></div></div></div></div></div><div class="col-12 col-xl-4"><div class="dashboard-panel seller-actions-panel"><div class="seller-side-heading">Seller actions</div><div class="seller-action-buttons"><a :href="seller.edit_url" class="btn btn-primary"><i class="bi bi-pencil-square"></i> Edit seller</a><a :href="indexUrl" class="btn btn-light border"><i class="bi bi-arrow-left"></i> Back</a></div></div></div></div><div class="row g-4 mb-4"><div v-for="item in [{k:'total',label:'Total books',tone:'blue',icon:'book'},{k:'approved',label:'Approved',tone:'green',icon:'check-circle'},{k:'pending',label:'Pending',tone:'orange',icon:'clock-history'},{k:'rejected',label:'Rejected',tone:'red',icon:'x-circle'}]" :key="item.k" class="col-12 col-sm-6 col-xl-3"><div class="seller-detail-stat" :class="'stat-'+item.tone"><i class="bi" :class="'bi-'+item.icon"></i><span>{{item.label}}</span><strong>{{payload.book_stats?.[item.k]||0}}</strong></div></div></div><div class="dashboard-panel seller-info-panel"><div class="seller-section-heading">Books by this seller</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Book</th><th>Status</th><th>Price</th><th>Stock</th><th>Added</th></tr></thead><tbody><tr v-for="book in payload.books||[]" :key="book.id"><td><img v-if="book.cover_url" :src="book.cover_url" alt="" style="width:42px;height:56px;object-fit:cover" class="me-2">{{book.title}}</td><td>{{book.status}}</td><td>{{book.price}}</td><td>{{book.stock}}</td><td>{{book.created_at}}</td></tr><tr v-if="!payload.books?.length"><td colspan="5" class="text-center py-4">No books found.</td></tr></tbody></table></div></div></div>
</template>
